from __future__ import annotations

from datetime import date, timedelta
from typing import List

from fastapi import APIRouter, HTTPException, Query
from pydantic import BaseModel

from services.market_data import TickerNotFoundError, fetch_prices

router = APIRouter()


class PricePoint(BaseModel):
    date: str
    close: float


class PriceHistoryResponse(BaseModel):
    ticker: str
    start: str
    end: str
    prices: List[PricePoint]


@router.get("/prices/{ticker}", response_model=PriceHistoryResponse)
def get_prices(
    ticker: str,
    days: int = Query(30, ge=1, le=365, description="Number of days of history to return"),
) -> PriceHistoryResponse:
    """Return recent daily adjusted close prices for a single ticker via yfinance."""
    end = date.today()
    start = end - timedelta(days=days)

    try:
        df = fetch_prices([ticker], start, end)
    except TickerNotFoundError as exc:
        raise HTTPException(
            status_code=404,
            detail={
                "error": "ticker_not_found",
                "ticker": exc.ticker,
                "suggestions": exc.suggestions,
            },
        )

    symbol = ticker.upper()
    series = df[symbol]
    prices = [
        PricePoint(date=idx.date().isoformat(), close=round(float(val), 4))
        for idx, val in series.dropna().items()
    ]

    return PriceHistoryResponse(
        ticker=symbol,
        start=start.isoformat(),
        end=end.isoformat(),
        prices=prices,
    )

